async function startApp(){try{$('#loginForm').addEventListener('submit',login);bind();}catch(error){console.error('Falha ao inicializar a interface:',error);setLoginMessage('Não foi possível iniciar a interface. Atualize a página e tente novamente.');return;}await loadPublicEnvironment();if(token){try{await loadApp();}catch(error){signOut(false);setLoginMessage(`Não foi possível carregar sua conta: ${error.message||'falha ao validar sessão'}. Entre novamente.`);}}}
